// ---- accounts: nickname + recovery code, backed by Supabase Auth ----
let acct=null,showCode=false;const myId=()=>acct?acct.id:(uid||localId);
const fmt=c=>(c.replace(/[^A-Z0-9]/gi,'').toUpperCase().match(/.{1,4}/g)||[]).join('-');
const hashCode=async c=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode('jsn:'+fmt(c))))].map(x=>x.toString(16).padStart(2,'0')).join('').slice(0,20);
const authEmail=async c=>`${await hashCode(c)}@${window.JSN_AUTH_DOMAIN||'accounts.jsn.invalid'}`;
const AL='ABCDEFGHJKLMNPQRSTUVWXYZ23456789',chk=x=>AL[[...x].reduce((a,c,i)=>a+(AL.indexOf(c)+1)*(i+1),0)%32];
const newCode=()=>{let c=[...crypto.getRandomValues(new Uint8Array(15))].map(x=>AL[x%32]).join('');c+=chk(c);return c.match(/.{4}/g).join('-')};
// nicknames are unique (any capitals). Check before creating an account so nobody ends up half signed up.
async function nameTaken(n,exceptId){const {data}=await sb.from('profiles').select('id,name').ilike('name',n.trim().replace(/[\\%_]/g,m=>'\\'+m)).limit(5);return (data||[]).some(p=>p.id!==exceptId&&p.name.trim().toLowerCase()===n.trim().toLowerCase())}
async function finishAcct(name,code,save){needSb();
 const session=sb.auth.getSession?await sb.auth.getSession():null;const user=session?.data?.session?.user||sbUser;
 if(!user)throw new Error('Supabase sign-in did not return a user session.');
 acct={name:name||'Volunteer',code:fmt(code),id:user.id};uid=user.id;$('who').textContent=acct.name;
 if(save){try{localStorage.setItem('jsn_acct',JSON.stringify({name:acct.name,code:acct.code}))}catch(e){}}
 try{await db.doc('profiles/'+acct.id).set({id:acct.id,name:acct.name})}catch(e){
  if(e&&e.code==='23505'){const {data:pp}=await sb.from('profiles').select('name').eq('id',acct.id).maybeSingle();
   if(pp&&pp.name){acct.name=pp.name}else{acct.name=(name||'Volunteer').slice(0,15)+'-'+Math.random().toString(36).slice(2,6);await db.doc('profiles/'+acct.id).set({id:acct.id,name:acct.name})}
   $('who').textContent=acct.name;try{localStorage.setItem('jsn_acct',JSON.stringify({name:acct.name,code:acct.code}))}catch(x){}
   NAMEMSG=`That nickname was taken, so you’re “${acct.name}”.`}else throw e}
 drawAcct();render();drawEv();drawBank();drawReq();
}
let NAMEMSG='';
async function createAccount(name){needSb();name=(name||'').trim();if(!name)throw new Error('Pick a nickname first.');if(name.length>20)throw new Error('Nicknames can be up to 20 characters.');if(await nameTaken(name))throw new Error('That nickname is already taken – please choose another one.');const code=newCode(),email=await authEmail(code);const {data,error}=await sb.auth.signUp({email,password:code});if(error)throw new Error(/invalid|domain/i.test(error.message)?'Supabase rejected the placeholder email address – see README_SUPABASE.md, Troubleshooting.':error.message);if(!data.user||!data.session)throw new Error('Account creation needs "Confirm email" switched OFF in Supabase (Authentication > Providers > Email).');await finishAcct(name,code,true);showCode=true}
