 if(!window.JSN_SUPABASE_URL||!window.JSN_SUPABASE_ANON_KEY||window.JSN_SUPABASE_URL.includes('YOUR-PROJECT')||window.JSN_SUPABASE_ANON_KEY.includes('YOUR_SUPABASE')){SBERR='Accounts are off: config.js still has the placeholder Supabase values (or your browser is showing an old saved copy – clear website data and reload).';console.warn('JSN Supabase config is missing. Copy config.example.js to config.js and add your project values.');return}
 if(!window.supabase||!window.supabase.createClient){SBERR='Could not load the Supabase library, so accounts are off. Check your internet connection, turn off any content blocker for this site, then reload.';$('msg').textContent=SBERR;return}
 sb=window.supabase.createClient(window.JSN_SUPABASE_URL,window.JSN_SUPABASE_ANON_KEY);db=makeDb(sb);assets=makeAssets(sb);
 const {data:{session}}=await sb.auth.getSession();sbUser=session?.user||null;uid=sbUser?.id||null;
 sb.auth.onAuthStateChange(async(_event,sess)=>{const was=sbUser&&sbUser.id;sbUser=sess?.user||null;uid=sbUser?.id||null;setTimeout(loadNotices);setTimeout(loadVolunteers,1500);if(REPSUB&&was!==(sbUser&&sbUser.id))REPSUB.reload();loadDetailsSoon();if(sbUser){const {data:p}=await sb.from('profiles').select('name,is_admin').eq('id',sbUser.id).maybeSingle();isAdmin=!!p?.is_admin;if(!acct){const saved=JSON.parse(localStorage.getItem('jsn_acct')||'null');if(saved?.code)await finishAcct(saved.name||p?.name||'Volunteer',saved.code,true)}else if(acct.id!==sbUser.id){acct=null}drawBank();drawReq();drawAcct();drawStories()}else{isAdmin=false;acct=null;drawAcct();drawBank();drawReq();drawStories()}});
 // Initial data listeners.
 db.collection('requests').onSnapshot(q=>{realReq=q.docs.map(d=>d.data());drawReq()},{filter:q=>q.or('status.eq.pending,t.gt.'+(Date.now()-60*864e5))});
 db.collection('ledger').onSnapshot(q=>{LEDGER=q.docs.map(d=>d.data());drawBank()});
 db.collection('rsvps').onSnapshot(q=>{RS=q.docs.map(d=>d.data());drawEv();loadDetailsSoon()},{filter:q=>q.gt('created_at',new Date(Date.now()-120*864e5).toISOString())});
 // map only needs open spots, spots cleaned in the last 2 weeks, and the signed-in person's own reports/cleans
 const repFilter=q=>{const me=sbUser&&sbUser.id,c=['cleaned.eq.false','cleaned_t.gt.'+(Date.now()-14*864e5)];if(me)c.push('by_user.eq.'+me,'cleaned_by.eq.'+me);return q.or(c.join(','))};
 REPSUB=db.collection('reports').onSnapshot(q=>{real=q.docs.map(d=>d.data()).filter(validRep);render();drawPop()},{filter:repFilter});
 db.collection('events').onSnapshot(q=>{events=q.docs.map(d=>d.data());drawEv();loadDetailsSoon()},{filter:q=>q.gt('when',Date.now()-2*864e5)});
 db.collection('news').onSnapshot(q=>{POSTS=q.docs.map(d=>d.data());drawStories()},{order:'t',limit:60});
